let replaceCover = (u) => {
    if (u.includes("novel-pic-r")) return u
    if (u.startsWith("https://")) u = u.substring(8)
    else u = u.substring(7)
    let uArr = u.split("/")
    uArr[0] = "https://p6-novel.byteimg.com/origin"
    let uArr2 = []
    uArr.forEach((x) => {
        if (!x.includes("?") && !x.includes("~")) uArr2.push(x)
        else uArr2.push(x.split("~")[0])
    })
    u = uArr2.join("/")
    return u
}

function getArguments(key) {
	const { source } = this;
	let open_argument = source.getVariable();
  try {
  		open_argument = JSON.parse(open_argument);
  } catch (e) {
    open_argument = {
      type: "novel",
      tone_id: "0",
    };
  }
  if (key) {
    return open_argument[key];
  } else {
    return open_argument;
  }
}

function setArguments(key, value) {
	const { source } = this;
	let open_argument = getArguments('');
	open_argument[key] = value;
	open_argument = JSON.stringify(open_argument);
	source.setVariable(open_argument);
	}

