@js:
var href = result;
var id = href.match(/\/book\/(\d+)/);
if (id) {
    var bookId = parseInt(id[1]);
    var coverId = bookId - 80;
    var idStr = coverId.toString();
    var len = idStr.length;
    if (len <= 3) {
        prefix = '0';
    } else {
        prefix = idStr.substring(0, len - 3);
    }    
    result = 'https://img.zgysbjw.com.cn/files/article/image/' +  prefix + '/' + idStr + '/' + idStr + 's.jpg';
} else {
    result = '';
}

